'use strict';

// MAIN //

/**
* Linear scale.
*
* @param {Array} mnmx - minmax array 
* @param {Number} points - number of points to generat in range
* @returns {Array} Points between range with linear scale
*/
function LinearScale( mnmx, points ) {
    var arr;
	var i;
	var d;

    arr = [];
	i = mnmx[ 0 ];
	d = ( mnmx[ 1 ] - mnmx[ 0 ] ) / points;
	while ( i <= mnmx[ 1 ] ) {
		arr.push( i );
		i += d;
	}
	return arr;
}

// EXPORT //

module.exports = LinearScale;